import pathlib, unittest, subprocess, shutil
ROOT=pathlib.Path(__file__).resolve().parents[1]
class TouchscreenReturnContract(unittest.TestCase):
 def test_return_requires_scan_availability_review_batch_and_status_only_recovery(self):
  s=(ROOT/'kiosk/return-ui.js').read_text()
  for token in ["req('/scan'",'candidate&&candidate.id!==root.id','already in the batch','/return/availability?ids=','Recorded condition:','Return location:','Required note if condition changed','Optional return note','at most 50 items','Confirm return',"req('/operation/status'",'s.uncertain=true','session_generation:c.generation','session_instance:c.instance']:
   self.assertIn(token,s)
  self.assertNotIn('anonymous_return',s)
 def test_html_and_shell_mount_return_flow(self):
  html=(ROOT/'kiosk/touchscreen.html').read_text();shell=(ROOT/'kiosk/touchscreen.js').read_text();server=(ROOT/'deploy/kiosk-server.py').read_text()
  self.assertIn('/return-ui.js',html);self.assertIn("window.beginReturn?.()",shell);self.assertIn("'/return-ui.js':'return-ui.js'",server)
 def test_current_return_ui_browser_behavior(self):
  node=shutil.which('node')
  if not node:self.skipTest('Node unavailable')
  source=(ROOT/'kiosk/return-ui.js').read_text()
  fixture=r'''global.window={checkoutSession:{generation:null,instance:null},listeners:{},addEventListener(k,f){this.listeners[k]=f},dispatchEvent(e){this.listeners[e.type]?.(e)}};
global.crypto={randomUUID(){return 'request-key'}};global.Event=class{constructor(type){this.type=type}};global.CustomEvent=class extends Event{constructor(type,o){super(type);this.detail=o?.detail}};
class N{constructor(tag){this.tag=tag;this.children=[];this.handlers={};this.textContent='';this.value='';this.placeholder='';this.disabled=false}append(...v){this.children.push(...v)}replaceChildren(...v){this.children=v}addEventListener(k,f){this.handlers[k]=f}setAttribute(k,v){this[k]=v}focus(){} }
global.Option=class extends N{constructor(text,value){super('option');this.textContent=text;this.value=value}};const host=new N('section');global.document={querySelector(){return host},createElement(t){return new N(t)}};
let calls=[],confirmCount=0,statusCount=0,done=null,availabilityCount=0;window.addEventListener('ccrate-flow-done',e=>done=e.detail);
global.fetch=async(path,opt={})=>{calls.push([path,opt]);if(path==='/api/inventory')return response([{id:'asset-id',name:'Asset'}]);if(path==='/scan')return response({entity:{id:JSON.parse(opt.body).code==='wrong'?'wrong-id':'asset-id',name:'Asset'}});if(path.startsWith('/return/availability'))return response({items:[{id:'asset-id',eligible:++availabilityCount>1,reason:availabilityCount===1?'Assigned item is not checked out':null,condition:'Ready',location:{id:'loc',name:'Bench'}}]});if(path==='/return/confirm'){confirmCount++;throw Error('response lost')}if(path==='/operation/status'){statusCount++;return response({status:'completed',id:'receipt',count:1})}throw Error('unexpected '+path)};function response(data){return {ok:true,json:async()=>data}}function all(n){return [n,...n.children.flatMap(all)]}function find(text){return all(host).find(n=>n.textContent===text)}function input(ph){return all(host).find(n=>n.placeholder===ph)}
'''+source+r'''
;(async()=>{await window.beginReturn();if(!all(host).some(n=>n.textContent.includes('Scan your member badge first.')))throw Error('badge gate absent');window.checkoutSession={generation:5,instance:'session-A'};window.dispatchEvent(new Event('ccrate-session-change'));await window.beginReturn();const q=input('Search by name or ID');q.value='Asset';await q.oninput();const choice=find('Asset');await choice.onclick();const scan=input('Scan item barcode');scan.value='wrong';await find('Verify scan and add').onclick();if(!all(host).some(n=>n.textContent.includes('does not match selected candidate')))throw Error('candidate mismatch not rejected');scan.value='match';await find('Verify scan and add').onclick();if(!all(host).some(n=>n.textContent.includes('Assigned item is not checked out')))throw Error('blocked availability reason not shown');scan.value='match';await find('Verify scan and add').onclick();if(!all(host).some(n=>n.textContent.includes('Bench')&&n.textContent.includes('Ready')))throw Error('condition/location not shown');const sel=all(host).find(n=>n.tag==='select');sel.value='Broken';sel.onchange();const issue=input('Required note if condition changed');issue.value='Cracked';issue.oninput();const retNote=input('Optional return note');retNote.value='On lower shelf';retNote.oninput();await find('Review return').onclick();await find('Confirm return').onclick();if(confirmCount!==1||!find('Check saved result'))throw Error('uncertain confirmation not recoverable');await find('Check saved result').onclick();if(statusCount!==1||confirmCount!==1||!find('Return complete'))throw Error('status recovery retried confirmation');find('Done').onclick();if(done?.generation!==5||done?.instance!=='session-A')throw Error('Done lost captured session');const payload=JSON.parse(calls.find(x=>x[0]==='/return/confirm')[1].body);const target=payload.targets[0];if(target.condition!=='Broken'||target.note!=='Cracked'||target.return_note!=='On lower shelf'||!payload.request_key)throw Error('return fields were not preserved')})().catch(e=>{console.error(e);process.exitCode=1});'''
  result=subprocess.run([node,'-e',fixture],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(result.returncode,0,result.stderr)
if __name__=='__main__':unittest.main()
